    if blocked is None:
        blocked = {}
    if pins is None:
        pins = {}

    names = sorted(packages)
    best_score = None
    best_versions = None
    bounds = {name: (limits[0], limits[1]) for name, limits in roots.items()}

    def search(assigned, current_bounds):
        nonlocal best_score, best_versions

        pending = set(current_bounds) - set(assigned)
        if not pending:
            score = tuple(assigned.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(assigned)
            return

