        low, high = current_bounds[name]
        for row in packages.get(name, []):
            version = row['version']
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue
            if not low <= version <= high:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_bounds = dict(current_bounds)
            valid = True

            for dependency in row.get('deps', []):
                if isinstance(dependency, dict):
                    dep_name = dependency['name']
                    dep_low = dependency['min']
                    dep_high = dependency['max']
                else:
                    dep_name = dependency
                    dep_low = float('-inf')
                    dep_high = float('inf')

                old_low, old_high = next_bounds.get(
                    dep_name, (float('-inf'), float('inf'))
                )
                new_low = max(old_low, dep_low)
                new_high = min(old_high, dep_high)
                if new_low > new_high:
                    valid = False
                    break
                next_bounds[dep_name] = (new_low, new_high)

                if dep_name in next_assigned:
                    dep_version = next_assigned[dep_name]
                    if not new_low <= dep_version <= new_high:
                        valid = False
                        break

            if valid:
                search(next_assigned, next_bounds)

    search({}, bounds)
    return best_versions
